//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package truebdd_test

import (
	"testing"
)

// concept-bodies-001-three-cases: A suite whose steps include matches and does not match, a set of operations and an optional word with meaning under their concepts gets patterns capturing each alternative and bodies that tell them apart
func TestConceptBodies001ThreeCases(t *testing.T) {
	s := New(t, "concept-bodies-001-three-cases")
	s.Given(`the "concept-bodies-cases" project tree`)
	s.And(`the System Architect's answer to every question is "1"`)
	s.When(`the System Architect runs "build steps --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches Concept pattern binds.*step="the calculator's output does not match .*captures="does not`)
	s.And(`stdout matches Concept pattern binds.*step="the Owner doubles 6" captures=.*doubl`)
	s.And(`stdout matches Concept pattern binds.*step="the Owner exactly halves 7" captures=.*exactly`)
	s.And(`stdout matches BUILD STEPS COMPLETE`)
	s.And(`no file outside "tmp" and "tests" changed`)
	s.And(`the shell command "go test -tags bdd -count=1 ./tests/calc/..." run in "." exits with code 0`)
	s.Done()
}

